// A day converts to an hour over the normal hours of the day, or to a month over the normal days; either floor met is enough (art.4(3)).
const hours = Number(get(ctx.entry, 'terms.normal_hours_per_day', 0));
if (!(hours > 0)) return false;
if (rate.amount / hours >= floor) return true;
const days = Number(get(ctx.entry, 'terms.normal_days_per_week', 0));
return (rate.amount * days * 52) / 12 >= get(ctx.lookup.minimum_wage.by_region, region, Infinity);

