const period = ctx.entry.terms.probation_period;
const jobClass = get(ctx.entry, 'employee_extension_data.probation_class', null);
if (jobClass === 'OTHER')
	return period.to <= add_working_days(period.from, ctx.lookup.other_working_days - 1, [], [6, 0]);
const days = calendar_distance_days(period.from, period.to) + 1;
if (jobClass === 'ENTERPRISE_MANAGER') return days <= ctx.lookup.enterprise_manager_days;
if (jobClass === 'COLLEGE_OR_ABOVE') return days <= ctx.lookup.college_days;
return days <= ctx.lookup.intermediate_days;

// Labour Code art.137(1): pregnancy (a) has no consent exception; an infant under 12 months (b) needs the day's consent.
const contract = ctx.subject.employment;
const date = ctx.entry.work_date;
const consent = get(ctx.entry, 'consent', {});
const children = get(contract, 'family', []).filter((member) => member.relation === 'CHILD');
const pregnant = children.some((child) => {
	const due = get(child, 'expected_on', null);
	const born = get(child, 'born_on', null);
	return due !== null && born === null && date >= add_months(due, -ctx.lookup.advance_months);
});
const night = clock_window_minutes(
	get(ctx.entry, 'actual_worked_intervals', []) ?? [],
	"Asia/Ho_Chi_Minh",
	ctx.lookup.night_from,
	ctx.lookup.night_to
);
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []);
if (pregnant) return night === 0 && overtime === 0;
const infant = children.some((child) => {
	const born = get(child, 'born_on', null);
	return born !== null && add_months(born, ctx.lookup.infant_months) > date;
});
if (!infant) return true;
return (
	(night === 0 || get(consent, 'night_work', false) === true) &&
	(overtime === 0 || get(consent, 'overtime', false) === true)
);

const contract = ctx.subject.employment;
const dob = get(contract, 'payroll.date_of_birth', null);
if (dob === null) return true;
const age = age_on(dob, ctx.entry.work_date);
if (age >= ctx.lookup.young_age) return true;
const worked = interval_minutes(get(ctx.entry, 'actual_worked_intervals', []) ?? []) / 60;
const week = ctx.reads.roster_entry.filter(
	(day) => day.work_date !== ctx.entry.work_date && day.work_date >= add_days(ctx.entry.work_date, -6)
);
const weekly =
	(sum(week.map((day) => interval_minutes(day.actual_worked_intervals ?? []))) +
		interval_minutes(get(ctx.entry, 'actual_worked_intervals', []) ?? [])) /
	60;
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []);
const night = clock_window_minutes(
	get(ctx.entry, 'actual_worked_intervals', []) ?? [],
	"Asia/Ho_Chi_Minh",
	ctx.lookup.night_from,
	ctx.lookup.night_to
);
if (age < ctx.lookup.child_age) {
	if (!(worked <= ctx.lookup.child_daily)) return false;
	if (!(weekly <= ctx.lookup.child_weekly)) return false;
	return overtime === 0 && night === 0;
}
const listed = get(contract, 'employee_extension_data.minor_listed_job', false) === true;
if (!(worked <= ctx.lookup.young_daily)) return false;
if (!(weekly <= ctx.lookup.young_weekly)) return false;
if (listed) return true;
return overtime === 0 && night === 0;

const on = String(ctx.entry.work_date);
const employer = (ctx.reads.entity_profile_version ?? []).find(
	(v) =>
		v.status === 'SEALED' &&
		v.effective_range != null &&
		String(v.effective_range.from) <= on &&
		(v.effective_range.to == null || String(v.effective_range.to) >= on),
);
if (employer == null) return false;
if (get(employer, 'entity_extension_data.rest_averaged_monthly', false) === true) {
	const from = month_start(on);
