	const siblings = ctx.reads.roster_entry.filter(
		(day) => day.work_date >= from && day.work_date <= to && day.work_date !== on
	);
	const rest = siblings.filter(
		(day) => interval_minutes(day.actual_worked_intervals ?? []) === 0
	).length;
	return siblings.length + 1 < ctx.lookup.month_records || rest >= ctx.lookup.rest_days;
}
const from = add_days(on, -(ctx.lookup.worked_days - 1));
const siblings = ctx.reads.roster_entry.filter(
	(day) => day.work_date >= from && day.work_date < on
);
const worked =
	siblings.filter((day) => interval_minutes(day.actual_worked_intervals ?? []) > 0).length + 1;
return siblings.length < ctx.lookup.worked_days - 1 || worked < ctx.lookup.worked_days;

const contract = ctx.subject.employment;
const agreed = get(contract, 'terms.normal_hours_per_day', ctx.lookup.daily_hours);
const cap = agreed > ctx.lookup.daily_hours ? ctx.lookup.weekly_arrangement_hours : ctx.lookup.daily_hours;
const worked = interval_minutes(get(ctx.entry, 'actual_worked_intervals', []) ?? []) / 60;
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []) / 60;
return worked - overtime <= cap;

const from = add_days(ctx.entry.work_date, -6);
const siblings = ctx.reads.roster_entry.filter(
	(day) => day.work_date >= from && day.work_date <= ctx.entry.work_date && day.work_date !== ctx.entry.work_date
);
const worked =
	sum(siblings.map((day) => interval_minutes(day.actual_worked_intervals ?? []))) +
	interval_minutes(get(ctx.entry, 'actual_worked_intervals', []) ?? []);
