	sum(siblings.map((day) => interval_minutes(day.planned_overtime_intervals ?? []))) +
	interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []);
return (worked - overtime) / 60 <= ctx.lookup.weekly_hours;

const contract = ctx.subject.employment;
const normal = Number(get(contract, 'terms.normal_hours_per_day', 0));
const overtime = interval_minutes(get(ctx.entry, 'planned_overtime_intervals', []) ?? []) / 60;
if (!(normal > 0)) return false;
if (!(overtime <= ctx.lookup.share * normal)) return false;
return normal + overtime <= ctx.lookup.daily_hours;

const previous = ctx.reads.roster_entry
	.filter((day) => day.work_date < ctx.entry.work_date && interval_minutes(day.actual_worked_intervals ?? []) > 0)
	.toSorted((left, right) => (left.work_date < right.work_date ? 1 : -1))[0];
if (previous === undefined) return true;
const intervals = previous.actual_worked_intervals ?? [];
const last = intervals[intervals.length - 1];
const end = get(last, 'end', null);
const firstInterval = get(ctx.entry, 'actual_worked_intervals', [])[0];
if (end === null) return true;
return elapsed_minutes(end, firstInterval.start) / 60 >= ctx.lookup.rest_hours;

