	review !== null &&
	get(review, 'month', '') === add_months(month_start(exit), -1).substring(0, 7) &&
	Number(get(review, 'daily_wage_vnd', 0)) > 0
);

const exit = ctx.entry.effective_range.to;
const review = get(ctx.entry, 'employee_extension_data.annual_leave_service_review', null);
if (review === null) return false;
if (String(get(review, 'year', '')) !== exit.substring(0, 4) || get(review, 'as_of', '') !== exit) return false;
const covered = ctx.reads.workplace_case_catalog_entry.some((record) => {
	if (!(record.opened_on <= exit)) return false;
	if (record.closed_on != null && !(record.closed_on >= exit)) return false;
	if (!(get(record, 'inputs.effective_from', '') <= exit)) return false;
	return get(record, 'inputs.effective_to', '') >= exit;
});
if (!covered) return true;
if (get(review, 'carry_previous_year_days', null) === null) return false;
return get(review, 'carry_second_previous_year_days', null) !== null;

const residency = get(ctx.entry, 'terms.residency_status', null);
const category = get(ctx.entry, 'terms.statutory_work_category', null);
if (residency === null) return false;
if (!ctx.lookup.residency_status.includes(residency)) return false;
return category === null || ctx.lookup.work_classification.includes(category);

return Object.keys(ctx.lookup.bounds).every((path) => {
	const value = get(ctx.entry, path, null);
	const bound = ctx.lookup.bounds[path];
	if (value === null) return get(bound, 'required', false) !== true;
	const minimum = get(bound, 'minimum', null);
	const maximum = get(bound, 'maximum', null);
	const allowed = get(bound, 'allowed', null);
	if (minimum !== null && value < minimum) return false;
	if (maximum !== null && value > maximum) return false;
	if (allowed !== null && !allowed.includes(value)) return false;
	return true;
});

